/**
 * Video lookup for a product.
 *
 * The manifest this reads is generated by tools/harvest-mallcom-videos.mjs. While
 * that run is still in flight (or for a product whose file was not harvested) the
 * lookup returns null and the page simply renders no video - the PDP is unchanged.
 *
 *   const v = videoForProduct('scar-b');   // { mp4, webm, poster } | null
 */
import { productVideos } from '../data/productVideos.generated.js';

const byDdurogaSlug = new Map();
const byMallcomSlug = new Map();

for (const v of productVideos) {
  for (const s of v.ddurogaProducts || []) if (!byDdurogaSlug.has(s)) byDdurogaSlug.set(s, v);
  for (const m of v.mallcomProducts || []) if (!byMallcomSlug.has(m)) byMallcomSlug.set(m, v);
}

/** The video for one of our products, or null. */
export function videoForProduct(slug) {
  const v = byDdurogaSlug.get(slug) || byMallcomSlug.get(slug);
  if (!v) return null;
  return { mp4: v.sources.mp4, webm: v.sources.webm, poster: v.poster };
}

/** Everything we know about one video file, keyed by its id. */
export const videoById = (id) => productVideos.find((v) => v.id === id) || null;

export const hasVideo = (slug) => Boolean(byDdurogaSlug.get(slug) || byMallcomSlug.get(slug));
